edits.newText:
/* Top Five by Volume Section */
.volume-list {
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.volume-row {
  display: grid;
  grid-template-columns: 120px 1fr 90px;
  align-items: center;
  gap: 20px;
}

.volume-label {
  font-weight: 600;
  color: #ffffff;
  font-size: 0.95rem;
}

.bar-track {
  width: 100%;
  height: 24px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #0284c7 0%, #38bdf8 100%);
  border-radius: 5px;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.35);
}

.volume-value {
  text-align: right;
  font-size: 0.95rem;
  font-weight: 600;
  color: #cbd5e1;
  font-feature-settings: "tnum";
}

.section-placeholder {

/* Top Five by Volume Section */
.volume-list {
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.volume-row {
  display: grid;
  grid-template-columns: 120px 1fr 90px;
  align-items: center;
  gap: 20px;
}

.volume-label {
  font-weight: 600;
  color: #ffffff;
  font-size: 0.95rem;
}

.bar-track {
  width: 100%;
  height: 24px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #0284c7 0%, #38bdf8 100%);
  border-radius: 5px;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.35);
}

.volume-value {
  text-align: right;
  font-size: 0.95rem;
  font-weight: 600;
  color: #cbd5e1;
  font-feature-settings: "tnum";
}

.section-placeholder {

