/* Top Five by Volume Section */
.volume-list {
  padding: 20px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.volume-row {
  display: grid;
  grid-template-columns: 120px 1fr 90px;
  align-items: center;
  gap: 20px;
}

.volume-label {
  font-weight: 600;
  color: #ffffff;
  font-size: 0.95rem;
}

.bar-track {
  width: 100%;
  height: 24px;
  background: rgba(255, 255, 255, 0.04);
